fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool {
    // If prefix is empty, every sequence starts with it.
    if p.is_empty() {
        return true;
    }
    // If sequence is shorter than prefix, cannot start with prefix.
    if v.len() < p.len() {
        return false;
    }
    // Check character by character.
    for i in 0..p.len() {
        if v[i] != p[i] {
            return false;
        }
    }
    true
}

fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>> {
    xs.into_iter()
        .filter(|v| has_prefix(v, &p))
        .collect()
}